<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import WorkspaceShell from '../components/workspace/WorkspaceShell.vue'
import { listProjects } from '../api/projects'
import * as api from '../api/skills'

const skills=ref([]); const projects=ref([]); const project=ref(''); const loading=ref(true); const error=ref(''); const modal=ref(false); const editing=ref(null); const busy=ref(false); const formError=ref(''); const executeModal=ref(false); const executing=ref(false); const executeTarget=ref(null); const executeInput=ref('{}'); const executeResult=ref(''); const executeError=ref('')
const form=reactive({name:'',version:'1.0.0',description:'',category:'custom',project:'',triggers:'{}',capabilities:'[]',tools:'[]',knowledge:'[]',input_schema:'{}',output_schema:'{}'})
const visibleSkills=computed(()=>project.value?skills.value.filter(item=>!item.project||item.project===project.value):skills.value)
function explain(err,fallback){if(err.response?.status===401)return'登录已过期，请重新登录。';if(err.response?.status===403)return'当前账号没有操作此 Skill 的权限。';const d=err.response?.data;if(typeof d?.detail==='string')return d.detail;const v=d&&Object.values(d)[0];return Array.isArray(v)?v.join('；'):(v||fallback)}
async function load(){loading.value=true;error.value='';try{[skills.value,projects.value]=await Promise.all([api.listSkills(),listProjects()])}catch(err){error.value=explain(err,'Skills 加载失败，请重试。')}finally{loading.value=false}}
function openForm(item=null){editing.value=item;Object.assign(form,{name:item?.name||'',version:item?.version||'1.0.0',description:item?.description||'',category:item?.category||'custom',project:item?.project||project.value||projects.value[0]?.id||'',triggers:JSON.stringify(item?.triggers||{},null,2),capabilities:JSON.stringify(item?.capabilities||[],null,2),tools:JSON.stringify(item?.tools||[],null,2),knowledge:JSON.stringify(item?.knowledge||[],null,2),input_schema:JSON.stringify(item?.input_schema||{},null,2),output_schema:JSON.stringify(item?.output_schema||{},null,2)});formError.value='';modal.value=true}
function json(text,label){try{return JSON.parse(text)}catch{formError.value=`${label}必须是有效 JSON。`;return null}}
async function save(){formError.value='';if(!form.name.trim()){formError.value='请输入 Skill 名称。';return}const payload={name:form.name.trim(),version:form.version.trim(),description:form.description,category:form.category,project:form.category==='custom'?(form.project||null):null};for(const [key,label] of [['triggers','触发条件'],['capabilities','能力列表'],['tools','工具列表'],['knowledge','知识依赖'],['input_schema','输入定义'],['output_schema','输出定义']]){const value=json(form[key],label);if(value===null)return;payload[key]=value}busy.value=true;try{if(editing.value)await api.updateSkill(editing.value.id,payload);else await api.createSkill(payload);ElMessage.success('Skill 已保存');modal.value=false;await load()}catch(err){formError.value=explain(err,'保存失败，请检查内容后重试。')}finally{busy.value=false}}
async function toggle(item){busy.value=true;try{await api.toggleSkill(item.id);ElMessage.success('Skill 状态已更新');await load()}catch(err){ElMessage.error(explain(err,'状态更新失败，请重试。'))}finally{busy.value=false}}
async function remove(item){if(!window.confirm(`确认删除 Skill“${item.name}”？`))return;busy.value=true;try{await api.deleteSkill(item.id);ElMessage.success('Skill 已删除');await load()}catch(err){ElMessage.error(explain(err,'删除失败，请重试。'))}finally{busy.value=false}}
async function openExecute(item){const raw=window.prompt(`执行 Skill“${item.name}”，请输入 JSON：`,'{}');if(raw===null)return;executeTarget.value=item;executeInput.value=raw;await execute();if(executeError.value)ElMessage.error(executeError.value);else window.alert(`执行结果：\\n${executeResult.value}`)}
async function execute(){executeError.value='';executeResult.value='';let input;try{input=JSON.parse(executeInput.value)}catch{executeError.value='输入必须是有效 JSON。';return}executing.value=true;try{const result=await api.executeSkill(executeTarget.value.id,input);executeResult.value=JSON.stringify(result,null,2);ElMessage.success('Skill 执行完成')}catch(err){executeError.value=explain(err,'Skill 执行失败，请检查输入或运行时配置。')}finally{executing.value=false}}
onMounted(load)
</script>
<template><WorkspaceShell active="skills"><div class="workspace-content model-page skills-page"><div class="page-title-row"><div><p class="workspace-eyebrow">SKILL REGISTRY</p><h1>Skills 管理</h1><p class="workspace-lead">管理智能体可调用的测试能力、触发条件和输入输出契约。</p></div><button class="primary-action" @click="openForm()">＋ 新建 Skill</button></div><section class="skills-toolbar"><label>项目筛选<select v-model="project"><option value="">全部可见 Skill</option><option v-for="item in projects" :key="item.id" :value="item.id">{{item.name}}</option></select></label><button class="text-action" :disabled="loading" @click="load">刷新 Skills</button></section><section class="skills-panel"><div v-if="loading" class="state-panel" role="status"><span class="loading-ring"></span><b>正在加载 Skills</b></div><div v-else-if="error" class="state-panel state-panel--error" role="alert"><b>暂时无法加载</b><p>{{error}}</p><button @click="load">重新加载</button></div><div v-else-if="!visibleSkills.length" class="skills-empty"><b>暂无可见 Skill</b><p>可以创建项目级自定义 Skill，或联系平台管理员启用共享 Skill。</p></div><table v-else class="skills-table"><thead><tr><th>名称</th><th>分类</th><th>范围</th><th>状态</th><th>版本</th><th>操作</th></tr></thead><tbody><tr v-for="item in visibleSkills" :key="item.id"><td><b>{{item.name}}</b><br><small>{{item.description||'暂无说明'}}</small></td><td>{{item.category_label}}</td><td>{{item.project_name||'共享'}}</td><td><span class="skills-chip" :class="{off:item.status!=='enabled'}">{{item.status_label}}</span></td><td>v{{item.version}}</td><td><div class="skills-actions"><button class="text-action" v-if="item.status==='enabled'" @click="openExecute(item)">Run</button><button class="text-action" @click="toggle(item)">{{item.status==='enabled'?'停用':'启用'}}</button><button class="text-action" @click="openForm(item)">编辑</button><button class="danger text-action" @click="remove(item)">删除</button></div></td></tr></tbody></table></section></div><Teleport to="body"><div v-if="modal" class="modal-backdrop" @click.self="!busy&&(modal=false)"><section class="config-modal skills-modal"><header><h2>{{editing?'编辑 Skill':'新建 Skill'}}</h2><button :disabled="busy" @click="modal=false">×</button></header><form @submit.prevent="save"><fieldset class="skills-form" :disabled="busy"><label>名称<input v-model="form.name" required></label><label>版本<input v-model="form.version" required></label><label>分类<select v-model="form.category"><option value="custom">自定义（项目级）</option><option value="core">核心（共享）</option><option value="specialized">专业（共享）</option><option value="auxiliary">辅助（共享）</option></select></label><label v-if="form.category==='custom'">所属项目<select v-model="form.project"><option value="">请选择项目</option><option v-for="item in projects" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>说明<textarea v-model="form.description" rows="2"></textarea></label><label>触发条件 JSON<textarea v-model="form.triggers" rows="2"></textarea></label><label>能力列表 JSON<textarea v-model="form.capabilities" rows="2"></textarea></label><p class="skills-hint">能力、工具、知识依赖使用 JSON 数组；输入和输出定义使用 JSON 对象。</p><label>工具列表 JSON<textarea v-model="form.tools" rows="2"></textarea></label><label>知识依赖 JSON<textarea v-model="form.knowledge" rows="2"></textarea></label><label>输入定义 JSON<textarea v-model="form.input_schema" rows="2"></textarea></label><label>输出定义 JSON<textarea v-model="form.output_schema" rows="2"></textarea></label><p v-if="formError" class="skills-error" role="alert">{{formError}}</p></fieldset><footer><button type="button" class="secondary-action" :disabled="busy" @click="modal=false">取消</button><button type="submit" class="primary-action" :disabled="busy">{{busy?'保存中…':'保存'}}</button></footer></form></section></div></Teleport></WorkspaceShell></template>
